 slug=row['source_lead_url'].split('/')[4];d=BASE/'raw'/slug;receipt=json.loads((d/'receipt.json').read_text()) if (d/'receipt.json').exists() else {};v=BASE/'parsed'/slug/'verification.json';validation=json.loads(v.read_text()) if v.exists() else {};pub=receipt.get('publisher_export',{});scopefile=BASE/'parsed'/slug/'publisher-scope.json';scope=json.loads(scopefile.read_text()) if scopefile.exists() else {};count=validation.get('record_count',0);checks=validation.get('checks',[]);core=[x['passed'] for x in checks if x['check'] not in ('native_export_parsed','native_text_matches_rendered','native_export_selection_binding')];pub_good=bool(pub.get('file')) and validation.get('publisher_record_count',0)>0 and all(any(x['check']==check and x['passed'] for x in checks) for check in ['native_text_matches_rendered','native_export_selection_binding'])
 status='standalone_e2e_pass' if core and all(core) else 'standalone_partial' if count else 'blocked' if receipt.get('error') else 'untested';inv=next(x for x in inventory if x['sequence']==row['sequence']);limitations=['Bounded substantive sample only; no complete jurisdiction corpus.', 'Unrendered later sections, independent publications and uncodified legislation are outside tested scope.', 'Only publisher HTML format tested; PDF/Word/Text/EPUB/MOBI controls are inventory observations.', 'No substantive table fidelity qualification when table_count is zero.']
